from pathlib import Path
import json,numpy as np,uproot
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
R=Path('runs/20261030_quick_no_upsilon');rows=json.loads((R/'summary.json').read_text());cases=json.loads((R/'cases.json').read_text())
fig,axes=plt.subplots(2,3,figsize=(14,7),gridspec_kw={'height_ratios':[3,1]})
for j,a in enumerate(cases):
 f=uproot.open(R/('m'+a['mass'])/'zero/asimov/fit/fitDiagnostics_toys.root');data=pred=cont=sig=None
 for i in range(1,5):
  d=f[f'shapes_fit_s/ch{i}'];v,e=d['total'].to_numpy();bw=np.diff(e);yy=d['data'].values('y')*bw;pp=v*bw;cc=d['dy'].values()*bw;ss=d['Zd'].values()*bw
  data=yy if data is None else data+yy;pred=pp if pred is None else pred+pp;cont=cc if cont is None else cont+cc;sig=ss if sig is None else sig+ss
 x=(e[:-1]+e[1:])/2;ax=axes[0,j];ax.plot(x,data,'k.',ms=3,label='Asimov: continuo + Y');ax.stairs(pred,e,color='tab:red',label='Fit totale senza Y');ax.stairs(cont,e,color='tab:green',ls='--',label='Chebyshev 3');ax.stairs(sig,e,color='tab:blue',label='DCB fitted');ax.set_title(f"m={a['mass']} GeV; quattro ere sommate");ax.set_ylabel('Eventi / bin');ax.legend(fontsize=7);ax.grid(alpha=.2);rx=axes[1,j];rx.axhline(0,color='gray');rx.plot(x,(data-pred)/np.sqrt(np.maximum(pred,1e-12)),'.',ms=3);rx.set_xlabel('Massa [GeV]');rx.set_ylabel('(A-fit)/sqrt(A-fit pred)',fontsize=7);rx.set_ylabel('(A-F)/sqrt(F)',fontsize=8);rx.grid(alpha=.2)
fig.suptitle('Dataset attesi senza fluttuazioni, r iniettato = 0\nLe Y sono presenti nella generazione e assenti nel fit');fig.tight_layout();fig.savefig(R/'asimov_fits.png',dpi=150);fig.savefig(R/'asimov_fits.pdf');plt.close(fig)
lines=['# Test rapido: assorbire le code Upsilon nel continuo','','## Configurazione','Tre masse 7.0, 7.5, 8.0 GeV; quattro ere combinate; finestre comuni 95% DCB e binning originali. Generatore SR Chebyshev3 + Upsilon1S + Upsilon2S, inizializzato ai fit B-only della precedente baseline SR+CR. Shape Upsilon originali. Segnale DCB originale e nuisance originali. Un solo scenario condizionale di normalizzazioni Y per massa, nessuna scansione della loro incertezza.','', '30 toy frequentist per massa/iniezione (r=0 oppure mediana limite atteso precedente SR+CR), 180 toy generati. Fit senza Y ottenuto fissando a zero tutte le 8 scale Y; continuo Cheb3 e nuisance del segnale profilati. Su ciascuno stesso toy anche fit di riferimento con Y fissate ai valori veri di generazione: isola omissione, non e un confronto con normalizzazioni Y libere o con la CR. Totale 360 fit di toy, tutti fit_status=0 e nessun r al bordo [-5,5]. Errori Hesse (--minos none), non validazione degli intervalli. CovQual non registrato per ciascun toy nell’albero standard: status0 non certifica ogni matrice. Nessun controllo multistart sistematico.','', 'Ulteriori 6 Asimov (senza fluttuazioni), fit senza Y. Nessun limite/p-value sui dati reali ricalcolato.','', '|Massa|Range GeV|r iniettato|r Asimov fitted|Bias Asimov|Bias medio toy ± errore MC|Spostamento appaiato senza-con Y ± errore MC|','|---|---|---|---|---|---|---|']
for r in rows:
 a=next(a for a in cases if float(a['mass'])==r['mass']);lines.append(f"|{r['mass']}|{a['range'][0]:.3f}–{a['range'][1]:.3f}|{r['injected']:.5f}|{r['asimov_r']:.5f}|{r['asimov_bias']:+.5f}|{r['mean_bias']:+.5f} ± {r['mean_bias_se']:.5f}|{r['paired_shift']:+.5f} ± {r['paired_shift_se']:.5f}|")
lines+=['','## Interpretazione','Nel singolo scenario nominale studiato, il bias Asimov è piccolo e la differenza appaiata con/senza Y è piccola rispetto alla dispersione dei fit. Questo è favorevole alla possibilità di assorbire le code nei tre range, non prova di assenza generale di bias.','', 'ATTENZIONE: a m8 con iniezione r=0.49538 il valore medio fitted è 0.96494 (bias +0.46956 ±0.12717 MC). Il riferimento con Y vere ha bias +0.46829: il problema non si elimina rimettendo le Y. Anche m7 con segnale presenta bias medio +0.03832 ±0.01805. Fluttuazioni, non-linearità/profiling e minimizzazione vanno approfonditi prima di usare la procedura per inferenza; questi risultati non validano il recupero del segnale.','', '30 toy/configurazione non sono sufficienti per validare copertura dei limiti o code dei p-value. Non testati scenari alternativi di normalizzazione Y o continuo generatore. Gli errori MC nelle tabelle sono errori sulla media, non errori di una singola misura. Asimov senza fluttuazioni non sostituisce i toy.','', 'File: summary.csv/json, toys.csv, validation.json, comandi/log/workspace e output ROOT in ogni sottodirectory. input precedenti invariati.'];(R/'REPORT.md').write_text('\n'.join(lines)+'\n')
